from __future__ import annotations

import ast
import io
import re
import tokenize
from collections.abc import Iterator
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SKIPPED_DIRS = {".venv", "node_modules", ".git", "dist", "test-results", "playwright-report", "samples", "__pycache__"}
# alembic files are generated by `alembic init` and `alembic revision`, edited minimally
GENERATED_DIRS = {ROOT / "backend" / "alembic"}
PYTHON_ROOTS = [ROOT / "backend", ROOT / "packages", ROOT / "scripts", ROOT / "tests", ROOT / "testkit"]
FRONTEND_ROOT = ROOT / "frontend"
STRING_LITERAL = re.compile(r"'(?:\\.|[^'\\\n])*'|\"(?:\\.|[^\"\\\n])*\"|`(?:\\.|[^`\\])*`")
DOCSTRING_OWNERS = (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)


def _is_skipped(path: Path) -> bool:
    if SKIPPED_DIRS.intersection(path.parts):
        return True
    return any(path.is_relative_to(generated) for generated in GENERATED_DIRS)


def _files(roots: list[Path], suffixes: tuple[str, ...]) -> Iterator[Path]:
    for root in roots:
        for path in sorted(root.rglob("*")):
            if path.suffix in suffixes and path.is_file() and not _is_skipped(path):
                yield path


def python_docstrings(source: str) -> list[int]:
    tree = ast.parse(source)
    return [
        getattr(node, "lineno", 1)
        for node in ast.walk(tree)
        if isinstance(node, DOCSTRING_OWNERS) and ast.get_docstring(node, clean=False) is not None
    ]


def python_comment_blocks(source: str) -> list[int]:
    starts: list[int] = []
    previous_line = -2
    run_start = 0
    for token in tokenize.generate_tokens(io.StringIO(source).readline):
        if token.type != tokenize.COMMENT or not token.line.lstrip().startswith("#"):
            continue
        line = token.start[0]
        if line == previous_line + 1:
            if run_start not in starts:
                starts.append(run_start)
        else:
            run_start = line
        previous_line = line
    return starts


def typescript_comment_blocks(source: str) -> list[int]:
    found: list[int] = []
    previous_was_line_comment = False
    for number, line in enumerate(source.splitlines(), start=1):
        if "/*" in STRING_LITERAL.sub("''", line):
            found.append(number)
        is_line_comment = line.lstrip().startswith("//")
        if is_line_comment and previous_was_line_comment:
            found.append(number)
        previous_was_line_comment = is_line_comment
    return found


def _violations() -> list[str]:
    problems: list[str] = []
    for path in _files(PYTHON_ROOTS, (".py",)):
        source = path.read_text(encoding="utf-8")
        rel = path.relative_to(ROOT)
        problems += [f"{rel}:{line} docstring" for line in python_docstrings(source)]
        problems += [f"{rel}:{line} multi-line comment block" for line in python_comment_blocks(source)]
    for path in _files([FRONTEND_ROOT], (".ts", ".tsx")):
        rel = path.relative_to(ROOT)
        problems += [
            f"{rel}:{line} block or multi-line comment"
            for line in typescript_comment_blocks(path.read_text(encoding="utf-8"))
        ]
    return problems


def test_python_detectors_flag_violations() -> None:
    assert python_docstrings('"""module"""\n\ndef f() -> None:\n    """doc"""\n') == [1, 3]
    assert python_comment_blocks("# one\nx = 1\n# two\n# three\ny = 2  # trailing\n# four\n") == [3]
    assert python_comment_blocks("x = 1  # a\n# b\n") == []


def test_typescript_detector_flags_violations() -> None:
    assert typescript_comment_blocks("const a = 1;\n/* block */\n") == [2]
    assert typescript_comment_blocks("return <div>{/* note */}</div>;\n") == [1]
    assert typescript_comment_blocks("// one\n// two\nconst b = 2;\n") == [2]
    assert typescript_comment_blocks("exclude: ['e2e/**'],\nconst url = 'http://x';\n// single\n") == []


def test_no_docstrings_or_comment_blocks_in_repo() -> None:
    assert _violations() == []
